  "webshop_itemprice_7days" varchar(255) COLLATE "pg_catalog"."default",
  "webshop_itemcount_30days" varchar(255) COLLATE "pg_catalog"."default",
  "webshop_itemprice_30days" varchar(255) COLLATE "pg_catalog"."default",
